using Npgsql; using System; await using var conn = new NpgsqlConnection("Host=localhost;Port=5433;Database=enjoyeveryday;Username=postgres;Password=postgres;Include Error Detail=true"); await conn.OpenAsync(); await using var cmd = new NpgsqlCommand("DO $$ DECLARE admin_id UUID; admin_role_id UUID; p_id UUID; BEGIN SELECT id INTO admin_id FROM users WHERE email = 'admin@littlestars.com'; IF admin_id IS NULL THEN RAISE NOTICE 'Admin not found'; RETURN; END IF; SELECT id INTO admin_role_id FROM roles WHERE name = 'Daycare Admin'; IF admin_role_id IS NULL THEN INSERT INTO roles (id, name, type) VALUES (gen_random_uuid(), 'Daycare Admin', 'System') RETURNING id INTO admin_role_id; END IF; INSERT INTO user_roles (user_id, role_id) VALUES (admin_id, admin_role_id) ON CONFLICT DO NOTHING; FOR p_id IN SELECT id FROM permissions LOOP INSERT INTO role_permissions (role_id, permission_id) VALUES (admin_role_id, p_id) ON CONFLICT DO NOTHING; END LOOP; RAISE NOTICE 'Done!'; END $$;", conn); await cmd.ExecuteNonQueryAsync(); Console.WriteLine("Updated permissions successfully.");
